<?php
require __DIR__.'/../../vendor/autoload.php'; $app=require __DIR__.'/../../bootstrap/app.php'; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use App\Models\Product; use App\Models\User; use App\Models\Warehouse; use App\Services\InventoryService; use Illuminate\Support\Facades\DB;
$db=DB::connection(); $identity=$db->selectOne('SELECT DATABASE() AS db, @@default_storage_engine AS engine'); $target='lubristore_einvoice_phase2_20261119_a7f3'; if($identity->db!==$target||strtolower($identity->engine)!=='innodb'){fwrite(STDERR,"ABORT target verification failed\n");exit(2);}
$user=User::where('email','phase2-qa-admin@example.test')->firstOrFail(); $source=Warehouse::where('code','QA-WH-P2-20261119')->firstOrFail(); $destination=app(InventoryService::class)->defaultWarehouse();
foreach(Product::where('sku','like','QA-F2-%')->orderBy('id')->get() as $product){ $sourceBalance=$source->inventories()->where('product_id',$product->id)->firstOrFail(); if((int)$sourceBalance->reserved_quantity!==0){fwrite(STDERR,"ABORT reserved stock found\n");exit(3);} $qty=(int)$sourceBalance->quantity; if($qty>0){app(InventoryService::class)->transfer($product,$source,$destination,$qty,'Reubicación de fixture QA para checkout',$user);} $fresh=$product->fresh(); $defaultBalance=$destination->inventories()->where('product_id',$product->id)->first(); echo "sku={$fresh->sku} stock={$fresh->stock} physical=".$fresh->inventories()->sum('quantity')." default_available=".((int)($defaultBalance?->quantity??0)-(int)($defaultBalance?->reserved_quantity??0))." reserved=".$fresh->inventories()->sum('reserved_quantity')."\n"; }